<?php require 'config/functions.php';$pageTitle='Katalog';$category=$_GET['category']??'';$q=trim($_GET['q']??'');$allowed=['Pria','Wanita','Unisex'];$where=[];$params=[];if(in_array($category,$allowed,true)){$where[]='category = ?';$params[]=$category;}if($q!==''){$where[]='name LIKE ?';$params[]='%'.$q.'%';}$sql='SELECT * FROM products'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY id DESC';$stmt=$pdo->prepare($sql);$stmt->execute($params);$products=$stmt->fetchAll();include 'partials/header.php';?><section class="container section"><span class="eyebrow">EXPLORE OUR COLLECTION</span><h1 class="page-title">Katalog Produk</h1><form class="filters" method="get"><input name="q" value="<?=e($q)?>" placeholder="Cari nama produk..."><select name="category"><option value="">Semua kategori</option><?php foreach($allowed as $c):?><option value="<?=e($c)?>" <?=$category===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select><button class="btn btn-dark">Cari</button></form><p class="muted"><?=count($products)?> produk ditemukan</p><div class="product-grid"><?php foreach($products as $product)include 'partials/card.php';?></div><?php if(!$products):?><p>Produk tidak ditemukan. Coba kata kunci lain.</p><?php endif;?></section><?php include 'partials/footer.php';?>